<?php
$tasks = task_rows($pdo, "t.archived_at IS NULL AND t.status = 'Completed'", [], 't.updated_at DESC');
?>
<section class="page-heading"><div><p class="eyebrow">DONE AND DUSTED</p><h1>Completed</h1><p class="muted">Semua tugas yang telah diselesaikan.</p></div></section>
<?php if (!$tasks): ?><div class="panel empty-state list-empty"><span class="empty-icon"><i class="bi bi-check-circle"></i></span><h3>Belum ada tugas selesai</h3><p>Tugas akan muncul di sini saat seluruh checklist selesai.</p></div><?php else: ?><div class="task-cards"><?php foreach ($tasks as $task): ?><article class="task-card"><div class="task-card-top"><div><a class="task-card-title" href="index.php?page=task-detail&id=<?= (int)$task['id'] ?>"><?= e($task['title']) ?></a><p class="task-card-description"><?= e($task['description'] ?: 'Tidak ada deskripsi.') ?></p></div><span class="status-pill status-completed">Completed</span></div><div class="task-card-bottom"><div class="task-tags"><span class="category-tag"><?= e($task['category_name'] ?: 'Tanpa kategori') ?></span><span class="priority priority-<?= strtolower(e($task['priority'])) ?>"><?= e($task['priority']) ?></span></div><span class="completed-date"><i class="bi bi-check-circle"></i> <?= e(date('d M Y', strtotime($task['updated_at']))) ?></span></div></article><?php endforeach; ?></div><?php endif; ?>
